mapper.select:
select t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code machineCode,t.action,t.log_id,t.log_id
logId,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id communityId,t.machine_name,t.machine_name
machineName,t.create_time createTime,ils.sensor_value sensorValue
from instrument_log t
left join instrument_log_sensor ils on t.log_id = ils.log_id and ils.status_cd = '0'
left join instrument i on t.machine_id = i.machine_id and ils.machine_id = i.machine_id and i.status_cd = '0'
left join instrument_sensor ise on ils.sensor_id = ise.sensor_id and ise.status_cd = '0'
where 1 =1

    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.action= #{action}


    and t.log_id= #{logId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.create_time >= #{queryStartTime}


    and t.create_time <= #{queryEndTime}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update instrument_log t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.machine_id= #{machineId}


    , t.machine_code= #{machineCode}


    , t.action= #{action}


    , t.community_id= #{communityId}


    , t.machine_name= #{machineName}

where 1=1

    and t.log_id= #{logId}

